package com.industrial.defect.entity.keyboard;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="keyboard_defects") public class KeyboardDefect { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="inspection_id") private KeyboardInspection inspection; @Column(name="defect_type") private String defectType; private String severity; private double confidence; @Column(name="key_label") private String keyLabel; @Column(name="row_index") private Integer rowIndex; @Column(name="column_index") private Integer columnIndex; private Double x1,y1,x2,y2; @Column(columnDefinition="TEXT") private String reason; @PrePersist void init(){if(id==null)id=UUID.randomUUID();} public void setInspection(KeyboardInspection v){inspection=v;} public void setDefectType(String v){defectType=v;} public void setSeverity(String v){severity=v;} public void setConfidence(double v){confidence=v;} public void setKeyLabel(String v){keyLabel=v;} public void setRowIndex(Integer v){rowIndex=v;} public void setColumnIndex(Integer v){columnIndex=v;} public void setX1(Double v){x1=v;} public void setY1(Double v){y1=v;} public void setX2(Double v){x2=v;} public void setY2(Double v){y2=v;} public void setReason(String v){reason=v;} }
